approve_onboard_payment:
mutation ApproveOnboardPaymentMutation($token: String!, $instrumentId: String, $isBillingAgreement: Boolean!, $supportedThreeDsExperiences: [ThreeDSPaymentExperience]) {
  attemptSetStickyFi(token: $token, instrumentId: $instrumentId) @include(if: $isBillingAgreement) {
    buyer {
      userId
      __typename
    }
    __typename
  }
  approveGuestSignUpPayment(token: $token) {
    buyer {
      userId
      email {
        stringValue
        __typename
      }
      name {
        fullName
        __typename
      }
      __typename
    }
    ...CartDonePage
    ...CompletedPaymentInfo
    fundingOptions {
      fundingInstrument {
        id
        lastDigits
        name
        nameDescription
        type
        __typename
      }
      __typename
    }
    merchant {
      name
      preferences {
        autoReturnToMerchant
        enablePaymentDataTransfer
        returnUrl
        __typename
      }
      __typename
    }
    shippingAddresses {
      fullAddress
      name {
        fullName
        __typename
      }
      __typename
    }
    paymentContingencies {
      ...threeDomainSecure
      ...threeDSContingencyData
      __typename
    }
    __typename
  }
}

